import { useState } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import FilterBar from './components/FilterBar';
import MenuSection from './components/MenuSection';
import About from './components/About';
import menuData from './data/menuData';
import LocalCafeIcon from '@mui/icons-material/LocalCafe';
import AcUnitIcon from '@mui/icons-material/AcUnit';
import CakeIcon from '@mui/icons-material/Cake';

function App() {
  const [activeRegion, setActiveRegion] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredItems = menuData.filter((item) => {
    const matchesRegion =
      activeRegion === 'All' || item.region === activeRegion;

    const search = searchTerm.toLowerCase();

    const matchesSearch =
      item.name.toLowerCase().includes(search) ||
      item.country.toLowerCase().includes(search) ||
      item.category.toLowerCase().includes(search) ||
      item.description.toLowerCase().includes(search) ||
      item.tags.join(' ').toLowerCase().includes(search);

    return matchesRegion && matchesSearch;
  });

  const hotDrinks = filteredItems.filter((item) => item.category === 'Hot Drinks');
  const coldDrinks = filteredItems.filter((item) => item.category === 'Cold Drinks');
  const desserts = filteredItems.filter((item) => item.category === 'Desserts');

  return (
    <>
      <Navbar />
      <Hero />

      <FilterBar
        activeRegion={activeRegion}
        setActiveRegion={setActiveRegion}
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
      />

      <MenuSection
        id="hot-drinks"
        title="Hot Drinks"
        subtitle="Traditional warm beverages from around the world"
        itemCount={hotDrinks.length}
        items={hotDrinks}
        icon={<LocalCafeIcon />}
      />

      <MenuSection
        id="cold-drinks"
        title="Cold Drinks"
        subtitle="Refreshing iced coffees and cold brews"
        itemCount={coldDrinks.length}
        items={coldDrinks}
        icon={<AcUnitIcon />}
      />

      <MenuSection
        id="desserts"
        title="Desserts"
        subtitle="Sweet treats and coffee-infused delights"
        itemCount={desserts.length}
        items={desserts}
        icon={<CakeIcon />}
      />

      <About />
    </>
  );
}

export default App;