import PublicIcon from '@mui/icons-material/Public';
import DiamondOutlinedIcon from '@mui/icons-material/DiamondOutlined';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';
import SpaIcon from '@mui/icons-material/Spa';
import '../styles/About.css';

function About() {
  const features = [
    {
      icon: <PublicIcon />,
      title: 'Global Origins',
      text: 'Authentic recipes and brewing techniques sourced from coffee cultures across five continents.',
    },
    {
      icon: <DiamondOutlinedIcon />,
      title: 'Premium Selection',
      text: 'Only the finest single-origin and specialty beans, carefully selected for each traditional recipe.',
    },
    {
      icon: <FavoriteBorderIcon />,
      title: 'Crafted with Care',
      text: 'Every cup prepared by skilled baristas who honor centuries-old traditions and techniques.',
    },
    {
      icon: <SpaIcon />,
      title: 'Sustainably Sourced',
      text: 'Partnerships with ethical farms and cooperatives committed to sustainable practices.',
    },
  ];

  return (
    <section className="about-section" id="about">
      <div className="container">
        <div className="about-header">
          <div className="about-subtitle-wrapper">
            <span className="about-line"></span>
            <span className="about-subtitle">OUR PHILOSOPHY</span>
            <span className="about-line"></span>
          </div>

          <h2 className="about-title">A World of Coffee in Every Cup</h2>

          <p className="about-description">
            At Monde Café, we believe coffee is more than a beverage—it is a journey through
            cultures, traditions, and stories passed down through generations. From the cardamom-
            infused coffees of the Arabian Peninsula to the sweet condensed milk blends of
            Southeast Asia.
          </p>
        </div>

        <div className="about-cards">
          {features.map((item, index) => (
            <div className="about-card" key={index}>
              <div className="about-card-icon">{item.icon}</div>
              <h3 className="about-card-title">{item.title}</h3>
              <p className="about-card-text">{item.text}</p>
            </div>
          ))}
        </div>

        <div className="about-quote">
          <p className="about-quote-text">"Coffee is a language in itself."</p>
          <span className="about-quote-author">— JACKIE CHAN</span>
        </div>
      </div>
    </section>
  );
}

export default About;