import '../styles/Hero.css';
import heroImage from '../assets/qahwa-arabiya.jpg';

function Hero() {
  return (
    <section className="hero-section">
      <div className="container">
        <div className="hero-wrapper">
          <div className="hero-left">
            <div className="hero-est">
              <span className="hero-line"></span>
              <span className="hero-est-text">EST. 2024</span>
            </div>

            <h1 className="hero-title">
              Exceptional <br />
              coffee <br />
              from around <br />
              the world
            </h1>

            <p className="hero-description">
              Embark on a sensory journey through the world's finest coffee
              traditions. From the aromatic spices of Arabian Qahwa to the
              velvety smoothness of Australian Flat White.
            </p>

            <div className="hero-buttons">
              <a href="#menu" className="hero-btn-primary">
                EXPLORE MENU
              </a>

              <a href="#about" className="hero-btn-secondary">
                LEARN OUR STORY →
              </a>
            </div>
          </div>

          <div className="hero-right">
            <img src={heroImage} alt="Coffee" className="hero-image" />

            <div className="hero-stats">
              <div className="hero-stat-box">
                <h3>38</h3>
                <p>DRINKS</p>
              </div>

              <div className="hero-stat-box">
                <h3>18</h3>
                <p>COUNTRIES</p>
              </div>

              <div className="hero-stat-box">
                <h3>3</h3>
                <p>CATEGORIES</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export default Hero;