import '../styles/FilterBar.css';

function FilterBar({ activeRegion, setActiveRegion, searchTerm, setSearchTerm }) {
  const categories = [
    'All',
    'Middle East',
    'Europe',
    'East Asia',
    'Southeast Asia',
    'South America',
    'North America',
    'Caribbean',
    'Africa',
    'Oceania',
  ];

  return (
    <section className="filter-section" id="menu">
      <div className="container">
        <div className="filter-header">
          <div className="filter-subtitle-wrapper">
            <span className="filter-line"></span>
            <span className="filter-subtitle">OUR SELECTION</span>
            <span className="filter-line"></span>
          </div>

          <h2 className="filter-title">International Coffee Menu</h2>

          <p className="filter-description">
            Each beverage tells a story of culture, tradition, and craftsmanship passed down
            through generations.
          </p>

          <div className="filter-search-box">
            <input
              type="text"
              placeholder="Search by name, country, or flavor..."
              className="filter-search-input"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="filter-buttons">
            {categories.map((cat) => (
              <button
                key={cat}
                className={`filter-btn ${activeRegion === cat ? 'active' : ''}`}
                onClick={() => setActiveRegion(cat)}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

export default FilterBar;